import net.minecraft.world.level.ItemLike;
import net.minecraft.world.phys.Vec3;

public class ItemVaultScenes {
    public static void storage(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("item_vault_storage", "Storing Items in Vaults");
        scene.configureBasePlate(0, 0, 5);
        scene.showBasePlate();
        scene.idle(5);
        Selection chests = util.select().fromTo(4, 3, 2, 3, 4, 3);
        Selection largeCog = util.select().position(3, 0, 5);
        Selection belt1 = util.select().fromTo(0, 2, 3, 2, 1, 5);
        Selection gearbox = util.select().position(2, 1, 2);
        Selection belt2 = util.select().fromTo(0, 1, 1, 2, 2, 1);
        Selection vault = util.select().fromTo(3, 2, 3, 4, 1, 1);
        scene.world().showSection(vault, Direction.NORTH);
        scene.idle(5);
        ElementLink chestLink = scene.world().showIndependentSection(chests, Direction.NORTH);
        scene.world().moveSection(chestLink, util.vector().of(-3.0, -2.0, 0.0), 0);
        scene.idle(10);
        scene.overlay().showOutline(PonderPalette.GREEN, (Object)"chestOutline", util.select().fromTo(1, 1, 2, 0, 2, 3), 40);
        scene.idle(10);
        scene.overlay().showLine(PonderPalette.GREEN, util.vector().of(2.0, 1.0, 2.0), util.vector().of(3.0, 1.0, 1.0), 30);
        scene.overlay().showLine(PonderPalette.GREEN, util.vector().of(2.0, 3.0, 2.0), util.vector().of(3.0, 3.0, 1.0), 30);
        scene.overlay().showLine(PonderPalette.GREEN, util.vector().of(2.0, 3.0, 4.0), util.vector().of(3.0, 3.0, 4.0), 30);
        scene.overlay().showOutline(PonderPalette.GREEN, (Object)"vaultOutline", vault, 40);
        scene.idle(10);
        BlockPos frontVault = util.grid().at(3, 2, 1);
        scene.overlay().showText(60).text("Item Vaults can be used to store large amounts of items").attachKeyFrame().placeNearTarget().pointAt(util.vector().blockSurface(frontVault, Direction.NORTH));
        scene.idle(70);
        scene.world().hideIndependentSection(chestLink, Direction.DOWN);
        scene.idle(15);
        ItemStack hand = AllItems.BRASS_HAND.asStack();
        scene.overlay().showControls(util.vector().blockSurface(frontVault, Direction.NORTH), Pointing.RIGHT, 40).showing((ScreenElement)AllIcons.I_MTD_CLOSE).withItem(hand);
        scene.idle(7);
        scene.overlay().showText(60).text("However, contents cannot be added or taken manually").attachKeyFrame().colored(PonderPalette.RED).placeNearTarget().pointAt(util.vector().blockSurface(frontVault, Direction.WEST));
        scene.idle(70);
        scene.world().showSection(largeCog, Direction.UP);
        scene.idle(5);

